def covering(S, T):
    res={}
    for t in [(a,b) for a in range(-20,21) for b in range(-20,21)]:
        if all(((r+t[0]),(c+t[1])) in T for r,c in S):
            res[t]=res.get(t,0)+1
    return sorted(res)
