def refv(S):
    rs=[r for r,c in S]; cs=[c for r,c in S]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    return {((r0+r1)-r,(c0+c1)-c) for r,c in S} # 180 rot
def refh(S):
    rs=[r for r,c in S]; cs=[c for r,c in S]
    r0,r1=min(rs),max(rs)
    return {((r0+r1)-r,c) for r,c in S}
def reflv(S):
    cs=[c for r,c in S]; c0,c1=min(cs),max(cs)
    return {(r,(c0+c1)-c) for r,c in S}
for name,T in [('rot180',refv(S)),('flipvert',refh(S)),('fliphorz',reflv(S))]:
    print(name, covering(T,co1))

H,W=21,13
inb=lambda r,c: 0<=r<H and 0<=c<W
def stamps(S,gin,H,W,cond):
    out=[]
    for a in range(-H,H):
        for b in range(-W,W):
            cs=[(r+a,c+b) for r,c in S]
            if all(inb(r,c) for r,c in cs) and cond(cs,gin):
                out.append((a,b))
    return out
